import { useState } from 'react';

// US1 MVP save form: a single address box. (Full add/edit with title,
// description, notes, tags arrives in US3 — T049.) Reports validation errors
// returned by the server, and surfaces the "already saved" case (FR-023).

export interface SaveOutcome {
  existing: boolean;
}

export function BookmarkEditor({
  onSave,
}: {
  onSave: (url: string) => Promise<SaveOutcome>;
}) {
  const [url, setUrl] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    if (!url.trim() || busy) return;
    setBusy(true);
    setError(null);
    setNote(null);
    try {
      const outcome = await onSave(url.trim());
      if (outcome.existing) {
        setNote('You already saved this — showing your existing bookmark.');
      }
      setUrl('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not save that address.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit}>
      <div className="save-box">
        <input
          type="text"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="Paste a web address to save…"
          aria-label="Web address"
          autoFocus
        />
        <button type="submit" disabled={busy || !url.trim()}>
          {busy ? 'Saving…' : 'Save'}
        </button>
      </div>
      {error ? <div className="form-error">{error}</div> : null}
      {note ? <div className="form-note">{note}</div> : null}
    </form>
  );
}

