import { useCallback, useEffect, useRef, useState } from 'react';
import type { Bookmark } from '../../shared/types';
import { api } from '../api/client';
import { BookmarkCard } from '../components/BookmarkCard';
import { BookmarkEditor, type SaveOutcome } from '../components/BookmarkEditor';
import { EmptyState } from '../components/EmptyState';

// Main MVP view (US1): save box + newest-first card list. Polls briefly while any
// bookmark is still enriching so preview details appear without a manual refresh.

export function ListPage() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loading, setLoading] = useState(true);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const refresh = useCallback(async () => {
    const res = await api.list();
    setBookmarks(res.bookmarks);
    return res.bookmarks;
  }, []);

  useEffect(() => {
    refresh().finally(() => setLoading(false));
  }, [refresh]);

  // Poll every 1.5s while something is pending; stop once all are enriched.
  useEffect(() => {
    const anyPending = bookmarks.some((b) => b.enrichStatus === 'pending');
    if (anyPending && !pollRef.current) {
      pollRef.current = setInterval(() => void refresh(), 1500);
    } else if (!anyPending && pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
    return () => {
      if (pollRef.current && !anyPending) {
        clearInterval(pollRef.current);
        pollRef.current = null;
      }
    };
  }, [bookmarks, refresh]);

  const handleSave = useCallback(
    async (url: string): Promise<SaveOutcome> => {
      const res = await api.create({ url });
      await refresh();
      return { existing: res.existing };
    },
    [refresh]
  );

  return (
    <div className="app">
      <header className="app-header">
        <h1>Bookmarks</h1>
        <p>Save a web address and it’ll show up below with a preview.</p>
      </header>

      <BookmarkEditor onSave={handleSave} />

      {loading ? null : bookmarks.length === 0 ? (
        <EmptyState
          title="No bookmarks yet"
          hint="Paste a web address above to save your first one."
        />
      ) : (
        <div className="card-list">
          {bookmarks.map((b) => (
            <BookmarkCard key={b.id} bookmark={b} />
          ))}
        </div>
      )}
    </div>
  );
}

