/**
 * Update an existing bookmark's editable content (US1 scope: title, description,
 * notes, tags — FR-003/FR-006). Address changes, archive, and read-later are
 * completed in US3 (T044). Only provided fields are changed; `updated_at` bumps.
 */
export function updateBookmark(
  db: DB,
  id: number,
  patch: { title?: string; description?: string; notes?: string; tags?: string[] }
): Bookmark | undefined {
  const current = getById(db, id);
  if (!current) return undefined;

  const title = patch.title !== undefined ? patch.title.trim() || current.url : current.title;
  const description = patch.description !== undefined ? patch.description : current.description;
  const notes = patch.notes !== undefined ? patch.notes : current.notes;

  const tx = db.transaction(() => {
    db.prepare(
      'UPDATE bookmarks SET title = ?, description = ?, notes = ?, updated_at = ? WHERE id = ?'
    ).run(title, description, notes, nowIso(), id);
    if (patch.tags !== undefined) setTags(db, id, patch.tags);
    const updated = getById(db, id)!;
    syncFts(db, updated);
    return updated;
  });
  return tx();
}

