:root {
  --bg: #f6f7f9;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1c2128;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #b91c1c;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  max-width: 860px;
  margin: 0 auto;
  padding: 24px 16px 64px;
}

.app-header h1 { margin: 0 0 4px; font-size: 1.6rem; }
.app-header p { margin: 0 0 20px; color: var(--muted); }

.save-box {
  display: flex;
  gap: 8px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  margin-bottom: 8px;
}
.save-box input {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
}
.save-box button {
  padding: 10px 18px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  cursor: pointer;
}
.save-box button:disabled { opacity: 0.6; cursor: default; }

.form-error { color: var(--danger); margin: 4px 2px 12px; font-size: 0.9rem; }
.form-note { color: var(--muted); margin: 4px 2px 12px; font-size: 0.9rem; }

.card-list { display: flex; flex-direction: column; gap: 12px; margin-top: 16px; }

.card {
  display: flex;
  gap: 14px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
}
.card .thumb {
  width: 96px;
  height: 72px;
  flex: 0 0 auto;
  border-radius: 8px;
  object-fit: cover;
  background: #eef1f5;
}
.card .body { min-width: 0; flex: 1; }
.card .title-row { display: flex; align-items: center; gap: 8px; }
.card .favicon { width: 16px; height: 16px; flex: 0 0 auto; }
.card a.title {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.card a.title:hover { color: var(--accent); text-decoration: underline; }
.card .url { color: var(--muted); font-size: 0.85rem; margin: 2px 0 6px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card .desc {
  margin: 0;
  color: #374151;
  font-size: 0.92rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card .pending { color: var(--muted); font-style: italic; font-size: 0.85rem; }

.link-button {
  background: none;
  border: none;
  color: var(--accent);
  cursor: pointer;
  font-size: 0.9rem;
  padding: 2px 0;
}
.link-button.edit { margin-left: auto; font-size: 0.85rem; }

.details-box {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  margin: 6px 0 12px;
}
.details-box label { display: flex; flex-direction: column; gap: 4px; font-size: 0.9rem; color: #374151; }
.details-box .muted { color: var(--muted); font-weight: 400; }
.details-box input,
.details-box textarea {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font: inherit;
}
.edit-actions { display: flex; gap: 8px; }
.edit-actions button {
  padding: 8px 14px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}
.edit-actions button.secondary { background: #e5e7eb; color: var(--text); }

.card.editing { display: block; }

.card .notes {
  margin: 6px 0 0;
  color: #4b5563;
  font-size: 0.88rem;
  white-space: pre-wrap;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.card .tag {
  background: #eef2ff;
  color: #3730a3;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 0.78rem;
}

.empty {
  text-align: center;
  color: var(--muted);
  padding: 48px 16px;
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 10px;
  margin-top: 16px;
}
.empty h2 { margin: 0 0 8px; color: var(--text); }

