import { useState } from 'react';
import type { Bookmark, UpdateBookmarkInput } from '../../shared/types';
import { parseTags } from '../lib/tags';

// A bookmark rendered as a readable card: preview image, favicon, title (opens
// the page), address, description, tags, and note. Long text is clamped via CSS
// (FR-007). Inline "Edit" lets a person fix the title, description, tags, or note
// — including a weird auto-fetched description (FR-003/FR-006, US1 scenario 4).
// Note formatting (headings/bullets) and address editing arrive in US3.

export function BookmarkCard({
  bookmark,
  onUpdate,
}: {
  bookmark: Bookmark;
  onUpdate: (id: number, patch: UpdateBookmarkInput) => Promise<void>;
}) {
  const [editing, setEditing] = useState(false);
  if (editing) {
    return (
      <EditCard
        bookmark={bookmark}
        onCancel={() => setEditing(false)}
        onSave={async (patch) => {
          await onUpdate(bookmark.id, patch);
          setEditing(false);
        }}
      />
    );
  }

  const enriching = bookmark.enrichStatus === 'pending';
  return (
    <div className="card">
      {/* Preview image opens the page too (FR-008) — the title is the primary link. */}
      <a
        className="thumb-link"
        href={bookmark.url}
        target="_blank"
        rel="noopener noreferrer"
        aria-label={`Open ${bookmark.title}`}
      >
        {bookmark.imageUrl ? (
          <img className="thumb" src={bookmark.imageUrl} alt="" loading="lazy" />
        ) : (
          <div className="thumb" aria-hidden="true" />
        )}
      </a>
      <div className="body">
        <div className="title-row">
          {bookmark.iconUrl ? (
            <img className="favicon" src={bookmark.iconUrl} alt="" loading="lazy" />
          ) : null}
          <a
            className="title"
            href={bookmark.url}
            target="_blank"
            rel="noopener noreferrer"
            title={bookmark.title}
          >
            {bookmark.title}
          </a>
          <button type="button" className="link-button edit" onClick={() => setEditing(true)}>
            Edit
          </button>
        </div>
        <div className="url">{bookmark.url}</div>
        {bookmark.description ? (
          <p className="desc">{bookmark.description}</p>
        ) : enriching ? (
          <p className="pending">Fetching preview…</p>
        ) : null}
        {bookmark.notes ? <p className="notes">{bookmark.notes}</p> : null}
        {bookmark.tags.length > 0 ? (
          <div className="tags">
            {bookmark.tags.map((t) => (
              <span className="tag" key={t}>
                {t}
              </span>
            ))}
          </div>
        ) : null}
      </div>
    </div>
  );
}

function EditCard({
  bookmark,
  onSave,
  onCancel,
}: {
  bookmark: Bookmark;
  onSave: (patch: UpdateBookmarkInput) => Promise<void>;
  onCancel: () => void;
}) {
  const [title, setTitle] = useState(bookmark.title);
  const [description, setDescription] = useState(bookmark.description);
  const [tags, setTags] = useState(bookmark.tags.join(', '));
  const [notes, setNotes] = useState(bookmark.notes);
  const [busy, setBusy] = useState(false);

  async function save() {
    setBusy(true);
    try {
      await onSave({ title, description, notes, tags: parseTags(tags) });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="card editing">
      <div className="body details-box">
        <label>
          Title
          <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} />
        </label>
        <label>
          Description <span className="muted">(fix a weird auto-fetched one here)</span>
          <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={2} />
        </label>
        <label>
          Tags <span className="muted">(comma-separated)</span>
          <input type="text" value={tags} onChange={(e) => setTags(e.target.value)} />
        </label>
        <label>
          Note
          <textarea value={notes} onChange={(e) => setNotes(e.target.value)} rows={3} />
        </label>
        <div className="edit-actions">
          <button type="button" onClick={save} disabled={busy}>
            {busy ? 'Saving…' : 'Save changes'}
          </button>
          <button type="button" className="secondary" onClick={onCancel} disabled={busy}>
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}

