import { useCallback, useEffect, useRef, useState } from 'react';
import type {
  Bookmark,
  CreateBookmarkInput,
  TagFilter,
  UpdateBookmarkInput,
} from '../../shared/types';
import { api, type TagInfo } from '../api/client';
import { BookmarkCard } from '../components/BookmarkCard';
import { BookmarkEditor, type SaveOutcome } from '../components/BookmarkEditor';
import { SearchBar } from '../components/SearchBar';
import { BackupPanel } from '../components/BackupPanel';
import { EmptyState } from '../components/EmptyState';

// Main view (US1 + US2): save box, search/filter bar, and the matching card list.
// Polls briefly while any bookmark is still enriching so previews appear live.

const EMPTY_FILTER: TagFilter = { view: 'all', sort: 'newest' };

export function ListPage() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [tags, setTags] = useState<TagInfo[]>([]);
  const [filter, setFilter] = useState<TagFilter>(EMPTY_FILTER);
  const [loading, setLoading] = useState(true);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const filterRef = useRef(filter);
  filterRef.current = filter;

  const refresh = useCallback(async () => {
    const [list, tagList] = await Promise.all([api.list(filterRef.current), api.tags()]);
    setBookmarks(list.bookmarks);
    setTags(tagList.tags);
  }, []);

  // Re-query whenever the filter changes.
  useEffect(() => {
    setLoading(true);
    refresh().finally(() => setLoading(false));
  }, [filter, refresh]);

  // Poll every 1.5s while something is pending; stop once all are enriched.
  useEffect(() => {
    const anyPending = bookmarks.some((b) => b.enrichStatus === 'pending');
    if (anyPending && !pollRef.current) {
      pollRef.current = setInterval(() => void refresh(), 1500);
    } else if (!anyPending && pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
    return () => {
      if (pollRef.current && !anyPending) {
        clearInterval(pollRef.current);
        pollRef.current = null;
      }
    };
  }, [bookmarks, refresh]);

  const handleSave = useCallback(
    async (input: CreateBookmarkInput): Promise<SaveOutcome> => {
      const res = await api.create(input);
      await refresh();
      return { existing: res.existing };
    },
    [refresh]
  );

  const handleUpdate = useCallback(
    async (id: number, patch: UpdateBookmarkInput): Promise<void> => {
      await api.update(id, patch);
      await refresh();
    },
    [refresh]
  );

  const isSearching =
    !!filter.text ||
    (filter.tagsAny?.length ?? 0) > 0 ||
    (filter.tagsAll?.length ?? 0) > 0 ||
    (filter.tagsNot?.length ?? 0) > 0;

  return (
    <div className="app">
      <header className="app-header">
        <h1>Bookmarks</h1>
        <p>Save a web address and it’ll show up below with a preview.</p>
      </header>

      <BackupPanel onImported={() => void refresh()} />

      <BookmarkEditor onSave={handleSave} />

      <SearchBar
        filter={filter}
        availableTags={tags}
        onChange={setFilter}
        onClear={() => setFilter(EMPTY_FILTER)}
      />

      {loading ? null : bookmarks.length === 0 ? (
        isSearching ? (
          <EmptyState
            title="No matches"
            hint="No bookmarks match your search or tag filter. Try clearing it."
          />
        ) : (
          <EmptyState
            title="No bookmarks yet"
            hint="Paste a web address above to save your first one."
          />
        )
      ) : (
        <div className="card-list">
          {bookmarks.map((b) => (
            <BookmarkCard key={b.id} bookmark={b} onUpdate={handleUpdate} />
          ))}
        </div>
      )}
    </div>
  );
}

