  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  border-radius: 10px;
  padding: 10px 12px;
  margin: 8px 0;
  font-size: 0.88rem;
}
.batch-count { font-weight: 600; }
.batch-sep { flex: 1; }
.batch-tag { display: inline-flex; gap: 4px; }
.batch-tag input { padding: 5px 8px; border: 1px solid var(--border); border-radius: 6px; }
.batch-toolbar button {
  padding: 6px 12px;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}
.batch-toolbar .link-button { background: none; color: var(--accent); padding: 0; }
.batch-toolbar .danger-btn { background: var(--danger); }

.tag-input { display: flex; flex-direction: column; gap: 6px; }
.tag-input-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 6px 8px;
}
.tag-input-chips input { border: none; outline: none; flex: 1; min-width: 100px; padding: 4px; font: inherit; }
.chip-removable { display: inline-flex; align-items: center; gap: 4px; }
.chip-removable button { border: none; background: none; cursor: pointer; color: #3730a3; font-size: 1rem; line-height: 1; }
.tag-suggestions { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-suggestion {
  border: 1px dashed var(--border);
  background: #f9fafb;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 0.78rem;
  cursor: pointer;
}

.notes-editor { display: flex; flex-direction: column; gap: 4px; }
.notes-editor textarea { padding: 8px 10px; border: 1px solid var(--border); border-radius: 8px; font: inherit; }
.notes-hint { color: var(--muted); font-size: 0.78rem; }
.notes-hint code { background: #f3f4f6; border-radius: 4px; padding: 0 4px; }

.card .notes h1, .card .notes h2, .card .notes h3 { margin: 6px 0 2px; font-size: 0.95rem; }
.card .notes ul { margin: 4px 0; padding-left: 20px; }
.card .notes p { margin: 4px 0; }

.card-list { display: flex; flex-direction: column; gap: 12px; margin-top: 16px; }

.card {
  display: flex;
  gap: 14px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
}
.card .thumb {
  width: 96px;
  height: 72px;
  flex: 0 0 auto;
  border-radius: 8px;
  object-fit: cover;
  background: #eef1f5;
}
.card .body { min-width: 0; flex: 1; }
.card .title-row { display: flex; align-items: center; gap: 8px; }
.card .favicon { width: 16px; height: 16px; flex: 0 0 auto; }
.card a.title {
