:root {
  --bg: #f6f7f9;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1c2128;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #b91c1c;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app {
  max-width: 860px;
  margin: 0 auto;
  padding: 24px 16px 64px;
}

.app-header h1 { margin: 0 0 4px; font-size: 1.6rem; }
.app-header p { margin: 0 0 20px; color: var(--muted); }

.save-box {
  display: flex;
  gap: 8px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  margin-bottom: 8px;
}
.save-box input {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
}
.save-box button {
  padding: 10px 18px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  cursor: pointer;
}
.save-box button:disabled { opacity: 0.6; cursor: default; }

.form-error { color: var(--danger); margin: 4px 2px 12px; font-size: 0.9rem; }
.form-note { color: var(--muted); margin: 4px 2px 12px; font-size: 0.9rem; }

.backup-panel {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin: 8px 0 14px;
  font-size: 0.88rem;
}
.backup-title { color: var(--muted); font-weight: 600; }
.backup-btn {
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--accent);
  text-decoration: none;
  cursor: pointer;
  font-size: 0.85rem;
}
.backup-btn.secondary { color: var(--text); }
.backup-msg { color: #166534; }
.backup-err { color: var(--danger); }

.search-bar {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  margin-bottom: 4px;
}
.search-row { display: flex; gap: 8px; align-items: center; }
.search-text {
  flex: 1;
  padding: 9px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
}
.sort-select {
  padding: 9px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.9rem;
  background: #fff;
}
.search-row .secondary {
  padding: 9px 14px;
  border: none;
  border-radius: 8px;
  background: #e5e7eb;
  color: var(--text);
  cursor: pointer;
}
.tag-filter { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 10px; }
.tag-filter-hint { color: var(--muted); font-size: 0.82rem; margin-right: 4px; }
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid var(--border);
  background: #fff;
  color: #374151;
  border-radius: 999px;
  padding: 3px 10px;
  font-size: 0.8rem;
  cursor: pointer;
}
.tag-chip .mode-badge {
  font-size: 0.68rem;
  text-transform: uppercase;
  border-radius: 999px;
  padding: 0 6px;
  color: #fff;
}
.tag-chip.mode-any { border-color: #2563eb; color: #1e40af; }
.tag-chip.mode-any .mode-badge { background: #2563eb; }
.tag-chip.mode-all { border-color: #7c3aed; color: #5b21b6; }
.tag-chip.mode-all .mode-badge { background: #7c3aed; }
.tag-chip.mode-not { border-color: #b91c1c; color: #991b1b; text-decoration: line-through; }
.tag-chip.mode-not .mode-badge { background: #b91c1c; }

.thumb-link { flex: 0 0 auto; display: block; }

.view-tabs { display: flex; gap: 4px; margin: 14px 0 4px; }
.view-tab {
  padding: 7px 16px;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--muted);
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
}
.view-tab.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.card.selected { outline: 2px solid var(--accent); }
.select-box { align-self: flex-start; margin-top: 4px; }
.card-actions { display: flex; gap: 12px; margin-top: 8px; }
.link-button.danger { color: var(--danger); }
.link-button.active-flag { color: #b45309; font-weight: 600; }

.batch-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  border-radius: 10px;
  padding: 10px 12px;
  margin: 8px 0;
  font-size: 0.88rem;
}
.batch-count { font-weight: 600; }
.batch-sep { flex: 1; }
.batch-tag { display: inline-flex; gap: 4px; }
.batch-tag input { padding: 5px 8px; border: 1px solid var(--border); border-radius: 6px; }
.batch-toolbar button {
  padding: 6px 12px;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}
.batch-toolbar .link-button { background: none; color: var(--accent); padding: 0; }
.batch-toolbar .danger-btn { background: var(--danger); }

.tag-input { display: flex; flex-direction: column; gap: 6px; }
.tag-input-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 6px 8px;
}
.tag-input-chips input { border: none; outline: none; flex: 1; min-width: 100px; padding: 4px; font: inherit; }
.chip-removable { display: inline-flex; align-items: center; gap: 4px; }
.chip-removable button { border: none; background: none; cursor: pointer; color: #3730a3; font-size: 1rem; line-height: 1; }
.tag-suggestions { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-suggestion {
  border: 1px dashed var(--border);
  background: #f9fafb;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 0.78rem;
  cursor: pointer;
}

.notes-editor { display: flex; flex-direction: column; gap: 4px; }
.notes-editor textarea { padding: 8px 10px; border: 1px solid var(--border); border-radius: 8px; font: inherit; }
.notes-hint { color: var(--muted); font-size: 0.78rem; }
.notes-hint code { background: #f3f4f6; border-radius: 4px; padding: 0 4px; }

.card .notes h1, .card .notes h2, .card .notes h3 { margin: 6px 0 2px; font-size: 0.95rem; }
.card .notes ul { margin: 4px 0; padding-left: 20px; }
.card .notes p { margin: 4px 0; }

.card-list { display: flex; flex-direction: column; gap: 12px; margin-top: 16px; }

.card {
  display: flex;
  gap: 14px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
}
.card .thumb {
  width: 96px;
  height: 72px;
  flex: 0 0 auto;
  border-radius: 8px;
  object-fit: cover;
  background: #eef1f5;
}
.card .body { min-width: 0; flex: 1; }
.card .title-row { display: flex; align-items: center; gap: 8px; }
.card .favicon { width: 16px; height: 16px; flex: 0 0 auto; }
.card a.title {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.card a.title:hover { color: var(--accent); text-decoration: underline; }
.card .url { color: var(--muted); font-size: 0.85rem; margin: 2px 0 6px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card .desc {
  margin: 0;
  color: #374151;
  font-size: 0.92rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card .pending { color: var(--muted); font-style: italic; font-size: 0.85rem; }

.link-button {
  background: none;
  border: none;
  color: var(--accent);
  cursor: pointer;
  font-size: 0.9rem;
  padding: 2px 0;
}
.link-button.edit { margin-left: auto; font-size: 0.85rem; }

.details-box {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  margin: 6px 0 12px;
}
.details-box label { display: flex; flex-direction: column; gap: 4px; font-size: 0.9rem; color: #374151; }
.details-box .muted { color: var(--muted); font-weight: 400; }
.details-box input,
.details-box textarea {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font: inherit;
}
.edit-actions { display: flex; gap: 8px; }
.edit-actions button {
  padding: 8px 14px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}
.edit-actions button.secondary { background: #e5e7eb; color: var(--text); }

.card.editing { display: block; }

.card .notes {
  margin: 6px 0 0;
  color: #4b5563;
  font-size: 0.88rem;
  white-space: pre-wrap;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.card .tag {
  background: #eef2ff;
  color: #3730a3;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 0.78rem;
}

.empty {
  text-align: center;
  color: var(--muted);
  padding: 48px 16px;
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 10px;
  margin-top: 16px;
}
.empty h2 { margin: 0 0 8px; color: var(--text); }

