25	  const [tags, setTags] = useState<TagInfo[]>([]);
26	  const [filter, setFilter] = useState<TagFilter>({ sort: 'newest' });
27	  const [selected, setSelected] = useState<Set<number>>(new Set());
28	  const [loading, setLoading] = useState(true);
29	  const [localReload, setLocalReload] = useState(0);
30	  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
31	  const stateRef = useRef({ view, filter });
32	  stateRef.current = { view, filter };
33	
34	  const refresh = useCallback(async () => {
35	    const { view: v, filter: f } = stateRef.current;
36	    const [list, tagList] = await Promise.all([api.list({ ...f, view: v }), api.tags()]);
37	    setBookmarks(list.bookmarks);
38	    setTags(tagList.tags);
39	  }, []);
40	
41	  useEffect(() => {
42	    setLoading(true);
43	    refresh().finally(() => setLoading(false));
44	  }, [view, filter, reloadToken, localReload, refresh]);
45	
46	  // Poll while anything is still enriching (mainly the 'all' view).
47	  useEffect(() => {
48	    const anyPending = bookmarks.some((b) => b.enrichStatus === 'pending');
49	    if (anyPending && !pollRef.current) {
50	      pollRef.current = setInterval(() => void refresh(), 1500);
51	    } else if (!anyPending && pollRef.current) {
52	      clearInterval(pollRef.current);
53	      pollRef.current = null;
54	    }
55	    return () => {
56	      if (pollRef.current && !anyPending) {
57	        clearInterval(pollRef.current);
58	        pollRef.current = null;
59	      }
60	    };
61	  }, [bookmarks, refresh]);
62	
63	  const bump = () => setLocalReload((n) => n + 1);
64	
65	  const handlers: CardHandlers = {
66	    onUpdate: async (id, patch: UpdateBookmarkInput) => {
67	      await api.update(id, patch);
68	      bump();
69	    },
70	    onDelete: async (id) => {
71	      await api.remove(id);
72	      bump();
73	    },
74	    onArchiveToggle: async (id, archived) => {
75	      await api.update(id, { archived });
76	      bump();
77	    },
78	    onReadLaterToggle: async (id, readLater) => {
79	      await api.update(id, { readLater });
80	      bump();
81	    },
82	    onToggleSelect: (id) =>
83	      setSelected((prev) => {
84	        const next = new Set(prev);
85	        if (next.has(id)) next.delete(id);
86	        else next.add(id);
87	        return next;
88	      }),
89	  };
90	
91	  const ids = () => [...selected];
92	  async function runBatch(fn: () => Promise<unknown>) {
93	    await fn();
94	    setSelected(new Set());
95	    bump();
96	  }
97	
98	  const isSearching =
99	    !!filter.text ||
100	    (filter.tagsAny?.length ?? 0) > 0 ||
101	    (filter.tagsAll?.length ?? 0) > 0 ||
102	    (filter.tagsNot?.length ?? 0) > 0;
103	
104	  return (
105	    <div>
106	      <SearchBar
107	        filter={filter}
108	        availableTags={tags}
109	        onChange={setFilter}
110	        onClear={() => setFilter({ sort: filter.sort })}
111	      />
112	
113	      <SavedSearchBar
114	        currentFilter={filter}
115	        onApply={(f) => setFilter({ ...f, sort: f.sort ?? filter.sort })}
116	      />
117	
118	      {selected.size > 0 ? (
119	        <BatchToolbar
120	          selectedCount={selected.size}
121	          showingCount={bookmarks.length}
122	          inArchivedView={view === 'archived'}
123	          onSelectAllShowing={() => setSelected(new Set(bookmarks.map((b) => b.id)))}
124	          onClear={() => setSelected(new Set())}
125	          onAddTag={(tag) => void runBatch(() => api.batch(ids(), 'addTag', tag))}
126	          onArchive={() => void runBatch(() => api.batch(ids(), 'archive'))}
127	          onUnarchive={() => void runBatch(() => api.batch(ids(), 'unarchive'))}
128	          onDelete={() => {
129	            if (window.confirm(`Delete ${selected.size} bookmark(s) permanently?`)) {
130	              void runBatch(() => api.batch(ids(), 'delete'));
131	            }
132	          }}
133	        />
134	      ) : null}
135	
136	      {loading ? null : bookmarks.length === 0 ? (
137	        isSearching ? (
138	          <EmptyState
139	            title="No matches"
140	            hint="Nothing matches your search or tag filter. Try clearing it."
141	          />
142	        ) : (
143	          <EmptyState title={emptyTitle} hint={emptyHint} />
144	        )
145	      ) : (
146	        <div className="card-list">
147	          {bookmarks.map((b) => (
148	            <BookmarkCard
149	              key={b.id}
150	              bookmark={b}
151	              selected={selected.has(b.id)}
152	              suggestions={tags.map((t) => t.name)}
153	              handlers={handlers}
154	            />
155	          ))}
156	        </div>
157	      )}
158	    </div>
159	  );
160	}

